import { sql } from "drizzle-orm";
import { index, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";

import { localeEnum } from "./_enums.ts";

/**
 * `users` — product-level account record.
 *
 * ## Relationship with the auth table
 *
 * Authentication tables (`user`, `session`, `account`, `verification`) are owned
 * and generated by Better Auth, not by this schema. They are created in the phase
 * that wires auth, not here. See docs/adr/0001-platform.md §Auth.
 *
 * This table therefore stores **no email and no password material**. It stores
 * the things the product owns: a public handle, a language, and lifecycle
 * timestamps. Email lives in exactly one place — the auth table — so there is
 * never a question of which copy is current, and a GDPR erasure touches one row.
 *
 * `id` is deliberately `text`, not `uuid`: it holds whatever identifier the auth
 * provider issued. Making it `uuid` would force a fixed id-generation strategy
 * on Better Auth just to make a type line up, and would break the day we add a
 * social login that issues its own subject id.
 */
export const users = pgTable(
  "users",
  {
    /**
     * Primary key == the auth provider's user id. Not a surrogate key.
     * There is no second id to keep in sync.
     */
    id: text("id").primaryKey(),

    /**
     * Public handle. Drives the future `/@username` route (PRD §31).
     * Nullable until Phase 3, when the onboarding step that sets it lands —
     * but the unique index is created now so the constraint is never retrofitted.
     */
    username: text("username"),

    /** User-selected UI language (roadmap §1: bilingual en/id). */
    locale: localeEnum("locale").notNull().default("en"),

    createdAt: timestamp("created_at", { withTimezone: true, mode: "date" })
      .notNull()
      .defaultNow(),

    updatedAt: timestamp("updated_at", { withTimezone: true, mode: "date" })
      .notNull()
      .defaultNow(),

    /**
     * Set on account deletion (PRD §6). Soft delete, not `DELETE`.
     *
     * The reason is §39: the XP ledger is the audit trail. A hard `DELETE FROM
     * users` would cascade into progression rows or force a purge of financial-
     * meaning records. Instead the row is tombstoned and the erasure flow
     * scrubs the identifying columns in a later phase. `xp_transactions` is
     * additionally `ON DELETE RESTRICT`, so this tombstone path is the *only*
     * way a user row can go away — there is no accidental cascade.
     */
    deletedAt: timestamp("deleted_at", { withTimezone: true, mode: "date" }),
  },
  (t) => [
    // Partial unique index: many deleted accounts may share a reclaimed handle,
    // but two live accounts may never collide.
    uniqueIndex("users_username_uidx")
      .on(t.username)
      .where(sql`${t.username} is not null`),
    // Serves the retention cohort query in docs/adr/0005-analytics-events.md
    // (D1/D7/D30 are measured from each user's first day).
    index("users_created_at_idx").on(t.createdAt),
  ],
);

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
